{"results": [{"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.421, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-001 (0.14)", "request matches LIM:selection_or_regression_to_the_mean (0.47); FAM:SF-APPA-001 auto_limited_by LIM:selection_or_regression_to_the_mean"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.367, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-005 (0.15)", "request matches RQC:RQC-054 (0.13); FAM:SF-APPA-005 auto_addresses_question RQC:RQC-054"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF-PAP-009", "label": "Study family SF-PAP-009: Coverage feasibility gate", "score": 0.338, "reached_via": ["FAM:SF29 auto_related_family (repeat_order_unknown) FAM:SF-PAP-009", "FAM:SF29 auto_related_family (repeat_order_unknown) FAM:SF-PAP-009"], "attributes": {"observed_research_question": "Coverage feasibility gate", "auto_outcome_status": "supported", "observed_hypothesis": "Lineup coverage (>=1 organizer, shaper, terminal) varies within team, is separable from talent/counts, and talent control behaves.", "observed_result": "G1 72 team-seasons with >=200 poss in both; G2 |rho(COVERED,TALENT)|=0.042, aux R2=0.203; G3 rho(TALENT,PPP)=+0.027", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "gate passed", "observed_sample_and_power": "90 team-seasons", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "420,993 possessions, 90 team-seasons; 3 gate criteria, beta not computed.", "observed_verdict": "supported", "observed_failure_type": "D_positive", "observed_notes": "NOT_RECORDED", "auto_confidence": "high (1.0)", "observed_member_records": "PAP-009"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF29"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-050"}, {"rel": "auto_uses_method", "node": "METH:correlation"}]}, {"id": "FAM:SF29", "label": "Study family SF29: Coverage > accumulation confirmatory (T_cov)", "score": 0.235, "reached_via": ["request matches the question or hypothesis of FAM:SF29 (0.21)", "request matches METH:regression (0.15); FAM:SF29 auto_uses_method METH:regression"], "attributes": {"observed_research_question": "Coverage > accumulation confirmatory (T_cov)", "auto_outcome_status": "rejected", "observed_hypothesis": "Lineups covering all three core roles score more per possession net of role counts and talent.", "observed_result": ["[APPM-042] Gate PASS (COVERED 30.0%; 72 team-seasons both strata; |Spearman(COVERED,TALENT)|=0.042; R2(COVERED~counts)=0.203; Spearman(TALENT,PPP)=+0.027). M1 COVERED b=+0.0067 (+0.67 pts/100), t=1.35, p=0.176, team-seas [cut; read_family for the full text]", "[PAP-010] Final: beta=+0.42 pts/100, t=0.53, p=0.595, CI[-1.15,+1.90]; MDE80=2.19 pts/100; n_ORGANIZER +2.35 (t=4.62). Prereg-recorded run (2026-07-13): +0.67 pts/100, t=1.35, p=0.176, CI[-0.28,+1.65]"], "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_verdict": "[APPM-042] null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_power_large_MDE"}, {"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}], "n_results": 4}

Stage 2. Using the retrieval result above (follow-up tools are allowed within the tool budget), complete steps 4 to 9
and reply with the final action. Output schema (all fields required):
{
 "research_concepts": [
  "concept"
 ],
 "methodological_questions": [
  "question"
 ],
 "historical_evidence": [
  {
   "id": "identifier of a record returned by a tool",
   "status_as_recorded": "outcome status exactly as stated in the record (supported | rejected | inconclusive | untestable | artifact | not a hypothesis test | no result recorded)",
   "finding": "what the record states, in its own terms"
  }
 ],
 "failed_approaches": [
  {
   "id": "identifier of a returned record",
   "what_failed": "approach",
   "why": "failure mechanism or limitation as recorded"
  }
 ],
 "evidence_establishes": [
  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
